package com.opensocket.aievent.core.issuetracking.change;
import java.time.OffsetDateTime; import java.util.Objects;
import com.opensocket.aievent.core.integration.identity.IntegrationRiskLevel;
public record ExternalChangePolicy(String tenantId,String policyId,String name,String connectionId,String projectMappingId,String externalProjectId,String issueType,ExternalChangeResourceType resourceType,String fieldPath,ExternalChangeDirection direction,ExternalChangeDecisionAction action,IntegrationRiskLevel riskLevel,boolean requiresReauthentication,boolean requiresApproval,boolean allowProviderMutation,int priority,ExternalChangePolicyStatus status,long version,OffsetDateTime effectiveFrom,OffsetDateTime expiresAt,OffsetDateTime updatedAt) {
 public ExternalChangePolicy { tenantId=req(tenantId,"tenantId");policyId=req(policyId,"policyId");name=req(name,"name");connectionId=norm(connectionId);projectMappingId=norm(projectMappingId);externalProjectId=norm(externalProjectId);issueType=norm(issueType);resourceType=Objects.requireNonNull(resourceType,"resourceType is required");fieldPath=norm(fieldPath);direction=Objects.requireNonNull(direction,"direction is required");action=Objects.requireNonNull(action,"action is required");riskLevel=riskLevel==null?IntegrationRiskLevel.UNKNOWN:riskLevel;status=Objects.requireNonNull(status,"status is required");if(priority<0)throw new IllegalArgumentException("priority cannot be negative");if(version<1)throw new IllegalArgumentException("version must be positive");updatedAt=Objects.requireNonNull(updatedAt,"updatedAt is required");if(expiresAt!=null&&effectiveFrom!=null&&!expiresAt.isAfter(effectiveFrom))throw new IllegalArgumentException("expiresAt must be after effectiveFrom");if(allowProviderMutation&&action!=ExternalChangeDecisionAction.ACCEPT&&action!=ExternalChangeDecisionAction.PROJECT)throw new IllegalArgumentException("allowProviderMutation requires ACCEPT or PROJECT"); }
 public boolean activeAt(OffsetDateTime now){return status==ExternalChangePolicyStatus.ACTIVE&&(effectiveFrom==null||!effectiveFrom.isAfter(now))&&(expiresAt==null||expiresAt.isAfter(now));}
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
